//! CC-ORTHO-FIX-FIL-ROMANCE 4: repair words a player saved before the orthography sweeps moved them.
//!
//! The banks quarantine or rename rows (estasyon -> istasyon). A saved miss or a My Words entry keeps the old string, so it would
//! be served as its own target and the new stored form would not be accepted for it. This module owns the repair:
//!
//! * `data/saved-word-map.tsv` (generated by tools/ortho/build_saved_word_map.py) maps each old form to its stored twin, or to
//!   nothing (HIDDEN: a quarantined row with no twin, such as `dae`). Scope is the eight languages in the map and no other.
//! * `rewrite_*` rename entries on load, merge a rename that lands on an entry that already exists (counts summed, the earlier
//!   due date kept), and return a log of every change so it can be reversed. Running one twice changes nothing.
//! * `is_hidden` keeps an unmapped quarantined word out of the due queue; it is never deleted from storage.
//! * `resolve` is what a served saved word is graded through: its current stored form, so the row's accepted spellings apply.
//!
//! No grading rule lives here. A language that is not in the map is never touched.

use crate::model::{CustomSet, MissEntry};
use crate::word_lists::Lists;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::OnceLock;
use unicode_normalization::UnicodeNormalization;

const MAP: &str = include_str!("../data/saved-word-map.tsv");
pub const LOG_KEY: &str = "byear_ortho_rewrite_log_v1";
const LOG_CAP: usize = 5000;

/// One change, enough to put the old text back.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Rewrite {
    /// "misses", "my_words" (a list in Lists) or "custom" (the older flat set).
    pub list: String,
    pub lang: String,
    pub old: String,
    pub new: String,
    /// The new form already existed, so the two entries became one.
    pub merged: bool,
}

type Table = HashMap<(String, String), Option<String>>;

fn nk(s: &str) -> String {
    s.nfc().collect()
}

fn table() -> &'static Table {
    static T: OnceLock<Table> = OnceLock::new();
    T.get_or_init(|| {
        let mut t = Table::new();
        for line in MAP.lines().filter(|l| !l.is_empty() && !l.starts_with('#')) {
            let c: Vec<&str> = line.split('\t').collect();
            if c.len() >= 3 {
                t.insert((c[0].to_string(), nk(c[1])), (!c[2].is_empty()).then(|| nk(c[2])));
            }
        }
        t
    })
}

/// Every (lang, old) in the map, for the tests.
#[cfg(test)]
pub(crate) fn entries() -> Vec<(String, String, Option<String>)> {
    table().iter().map(|((l, o), n)| (l.clone(), o.clone(), n.clone())).collect()
}

/// The stored twin of an old form, if it has one.
fn twin(lang: &str, word: &str) -> Option<&'static str> {
    table().get(&(lang.to_string(), nk(word))).and_then(|n| n.as_deref())
}

/// An old form with no twin: quarantined, not Filipino (and so on). Kept in storage, never served.
pub fn is_hidden(lang: &str, word: &str) -> bool {
    matches!(table().get(&(lang.to_string(), nk(word))), Some(None))
}

/// The word to serve and grade: the stored twin of an old form, else the word itself.
pub fn resolve(lang: &str, word: &str) -> String {
    twin(lang, word).map_or_else(|| word.to_string(), str::to_string)
}

/// Repair the saved misses. A rename that lands on an existing entry merges into it.
pub fn rewrite_misses(list: &mut Vec<MissEntry>) -> Vec<Rewrite> {
    let mut log = Vec::new();
    let mut touched: Vec<String> = Vec::new();
    for e in list.iter_mut() {
        if let Some(new) = twin(&e.lang, &e.word) {
            log.push(Rewrite { list: "misses".into(), lang: e.lang.clone(), old: e.word.clone(), new: new.to_string(), merged: false });
            e.word = new.to_string();
            touched.push(crate::misses::miss_key(&e.word, &e.lang));
        }
    }
    // Merge entries that now share an identity, only those this run renamed.
    let mut i = 0;
    while i < list.len() {
        let key = crate::misses::miss_key(&list[i].word, &list[i].lang);
        if touched.contains(&key) {
            let mut j = i + 1;
            while j < list.len() {
                if crate::misses::miss_key(&list[j].word, &list[j].lang) == key {
                    let other = list.remove(j);
                    let keep = &mut list[i];
                    keep.misses += other.misses;
                    keep.ts = keep.ts.max(other.ts);
                    if other.due < keep.due {
                        keep.due = crate::review::earlier_due(keep.due, other.due);
                        keep.review = other.review.clone().or(keep.review.take());
                    }
                    if let Some(r) = log.iter_mut().find(|r| r.list == "misses" && r.lang == keep.lang && r.new == keep.word && !r.merged) {
                        r.merged = true;
                    }
                } else {
                    j += 1;
                }
            }
        }
        i += 1;
    }
    log
}

/// Repair My Words lists (the Lists store). Stars and the earliest added time survive a merge.
pub fn rewrite_lists(lists: &mut Lists, now: f64) -> Vec<Rewrite> {
    let mut log = Vec::new();
    for l in lists.lists.iter_mut() {
        let before = log.len();
        let mut i = 0;
        while i < l.entries.len() {
            let (lang, text) = (l.entries[i].lang.clone(), l.entries[i].text.clone());
            if let Some(new) = twin(&lang, &text) {
                let dup = l.entries.iter().enumerate().position(|(j, e)| j != i && e.lang == lang && nk(&e.text) == new);
                if let Some(j) = dup {
                    let gone = l.entries.remove(i);
                    let j = if j > i { j - 1 } else { j };
                    l.entries[j].starred |= gone.starred;
                    if gone.added_at > 0.0 && (l.entries[j].added_at == 0.0 || gone.added_at < l.entries[j].added_at) {
                        l.entries[j].added_at = gone.added_at;
                    }
                    log.push(Rewrite { list: "my_words".into(), lang, old: text, new: new.to_string(), merged: true });
                    continue;
                }
                l.entries[i].text = new.to_string();
                log.push(Rewrite { list: "my_words".into(), lang, old: text, new: new.to_string(), merged: false });
            }
            i += 1;
        }
        if log.len() > before {
            l.updated_at = now;
        }
    }
    log
}

/// Repair the older flat My Words set.
pub fn rewrite_custom(c: &mut CustomSet) -> Vec<Rewrite> {
    let mut log = Vec::new();
    let mut i = 0;
    while i < c.words.len() {
        let text = c.words[i].clone();
        let lang = c.word_lang.get(&text).cloned().unwrap_or_else(|| c.speak_lang.clone());
        let Some(new) = twin(&lang, &text) else {
            i += 1;
            continue;
        };
        let merged = c.words.iter().enumerate().any(|(j, w)| j != i && nk(w) == new);
        if let Some(l) = c.word_lang.remove(&text) {
            c.word_lang.entry(new.to_string()).or_insert(l);
        }
        if let Some(b) = c.word_batch.remove(&text) {
            c.word_batch.entry(new.to_string()).or_insert(b);
        }
        if c.custom_marks.remove(&text) {
            c.custom_marks.insert(new.to_string());
        }
        if merged {
            c.words.remove(i);
        } else {
            c.words[i] = new.to_string();
            i += 1;
        }
        log.push(Rewrite { list: "custom".into(), lang, old: text, new: new.to_string(), merged });
    }
    log
}

/// Append a run's rewrites to the device log, newest last, capped.
pub fn record(log: &[Rewrite]) {
    if log.is_empty() {
        return;
    }
    let mut all: Vec<Rewrite> = crate::storage::get_json(LOG_KEY).unwrap_or_default();
    all.extend_from_slice(log);
    if all.len() > LOG_CAP {
        all.drain(..all.len() - LOG_CAP);
    }
    crate::storage::set_json(LOG_KEY, &all);
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::MissEntry;

    fn miss(word: &str, lang: &str, misses: u32, due: f64) -> MissEntry {
        MissEntry { word: word.into(), lang: lang.into(), tier: "hard".into(), misses, box_: 0, due, ts: due, review: None }
    }

    /// The bank holds the entry exactly (zh entries are `pinyin|hanzi`, compared whole).
    fn in_bank(lang: &str, w: &str) -> bool {
        ["easy", "medium", "hard", "expert"].iter().any(|t| crate::words::tier_for(lang, t).iter().any(|e| nk(e) == nk(w)))
    }

    #[test]
    fn the_map_is_scoped_consistent_and_leaves_de_and_en_alone() {
        let scope = ["fil", "es", "fr", "pt", "vi", "hi", "ru", "zh"];
        let all = entries();
        assert!(all.len() > 50, "the map is empty or missing");
        for (lang, old, new) in all {
            assert!(scope.contains(&lang.as_str()), "{lang}: outside the eight languages");
            assert!(!in_bank(&lang, &old), "{lang} {old}: an old form is a current bank row");
            if let Some(n) = new {
                assert!(in_bank(&lang, &n), "{lang} {old} -> {n}: the stored twin is not a bank row");
            }
        }
        for l in ["de", "en", "ja", "ko", "pl", "sw", "ar"] {
            assert_eq!(resolve(l, "estasyon"), "estasyon");
            assert!(!is_hidden(l, "dae"));
        }
    }

    #[test]
    fn a_saved_miss_estasyon_is_graded_through_istasyon() {
        let served = resolve("fil", "estasyon");
        assert_eq!(served, "istasyon");
        assert!(crate::norm::answer_matches_in("fil", "istasyon", &served, false), "istasyon typed for the saved estasyon");
        assert!(crate::norm::answer_matches_in("fil", "estasyon", &served, false), "and the old spelling still counts");
    }

    #[test]
    fn rewriting_twice_changes_nothing_and_logs_every_rename() {
        let mut l = vec![miss("estasyon", "fil", 3, 500.0), miss("kompanya", "fil", 1, 100.0), miss("dae", "fil", 2, 50.0)];
        let first = rewrite_misses(&mut l);
        assert_eq!(first.len(), 1, "{first:?}");
        assert_eq!((first[0].old.as_str(), first[0].new.as_str()), ("estasyon", "istasyon"));
        let snapshot = l.iter().map(|e| (e.word.clone(), e.misses, e.due as i64)).collect::<Vec<_>>();
        assert!(rewrite_misses(&mut l).is_empty(), "the second run must log nothing");
        assert_eq!(snapshot, l.iter().map(|e| (e.word.clone(), e.misses, e.due as i64)).collect::<Vec<_>>());
    }

    #[test]
    fn both_forms_saved_become_one_entry_with_summed_counts_and_the_earlier_due() {
        for order in [0, 1] {
            let mut l = vec![miss("estasyon", "fil", 3, 900.0), miss("istasyon", "fil", 2, 400.0)];
            if order == 1 {
                l.reverse();
            }
            let log = rewrite_misses(&mut l);
            assert_eq!(l.len(), 1, "order {order}");
            assert_eq!((l[0].word.as_str(), l[0].misses, l[0].due as i64), ("istasyon", 5, 400));
            assert!(log.iter().any(|r| r.merged), "{log:?}");
            assert!(rewrite_misses(&mut l).is_empty());
        }
    }

    #[test]
    fn an_unmapped_quarantined_word_is_hidden_and_kept() {
        assert!(is_hidden("fil", "dae") && is_hidden("fil", "dai") && is_hidden("fil", "babaeng"));
        assert!(!is_hidden("fil", "istasyon") && !is_hidden("fil", "estasyon"), "a mapped word is repaired, not hidden");
        let mut l = vec![miss("dae", "fil", 2, 10.0)];
        assert!(rewrite_misses(&mut l).is_empty());
        assert_eq!(l.len(), 1, "never deleted from storage");
    }

    #[test]
    fn my_words_lists_are_repaired_and_merged() {
        use crate::word_lists::{ListEntry, ListSource, Lists, Order, WordList};
        let e = |t: &str, star: bool, at: f64| ListEntry { text: t.into(), lang: "fil".into(), added_at: at, starred: star };
        let mut lists = Lists::default();
        lists.lists.push(WordList {
            id: "a".into(),
            profile: String::new(),
            name: "x".into(),
            created_at: 1.0,
            updated_at: 1.0,
            source: ListSource::Manual,
            entries: vec![e("estasyon", true, 5.0), e("istasyon", false, 9.0), e("saging", false, 1.0)],
            deleted_at: None,
            order: Order::default(),
            key: None,
        });
        let log = rewrite_lists(&mut lists, 77.0);
        let l = &lists.lists[0];
        assert_eq!(l.entries.len(), 2);
        assert_eq!((l.entries[0].text.as_str(), l.entries[0].starred, l.entries[0].added_at as i64), ("istasyon", true, 5));
        assert_eq!(l.updated_at as i64, 77);
        assert_eq!(log.len(), 1);
        assert!(rewrite_lists(&mut lists, 99.0).is_empty());
        assert_eq!(lists.lists[0].updated_at as i64, 77, "an empty run must not touch updated_at");
    }

    #[test]
    fn the_older_flat_set_is_repaired() {
        let mut c = CustomSet { words: vec!["estasyon".into(), "saging".into()], speak_lang: "fil".into(), ..Default::default() };
        let log = rewrite_custom(&mut c);
        assert_eq!(c.words, vec!["istasyon".to_string(), "saging".to_string()]);
        assert_eq!(log.len(), 1);
        assert!(rewrite_custom(&mut c).is_empty());
    }

    #[test]
    fn a_saved_dae_is_not_served_but_stays_in_storage() {
        let mut st = crate::model::AppState::default();
        st.misses = vec![miss("dae", "fil", 2, 10.0), miss("saging", "fil", 1, 10.0)];
        let due = crate::misses::due_misses_at(&st, 1000.0);
        assert_eq!(due, vec![1], "dae must not be in the due queue");
        assert_eq!(st.misses.len(), 2, "and it is still in the saved list");
        assert!(rewrite_misses(&mut st.misses).is_empty());
        assert_eq!(st.misses.len(), 2);
    }
}
